"""Enumerate and cross-check the four Catalan families by size."""
from functools import lru_cache
from math import comb
from typing import Optional, Tuple

PlaneTree = Tuple[str, Tuple]
Forest = Tuple[PlaneTree, ...]
BinTree = Optional[Tuple[str, "BinTree", "BinTree"]]


def catalan(n: int) -> int:
    return comb(2 * n, n) // (n + 1)


@lru_cache(maxsize=None)
def forests_with_nodes(n: int) -> Tuple[Forest, ...]:
    if n == 0:
        return ((),)
    out = []
    for k in range(1, n + 1):
        for g in forests_with_nodes(k - 1):
            first = ("node", g)
            for rest in forests_with_nodes(n - k):
                out.append((first,) + rest)
    return tuple(out)


@lru_cache(maxsize=None)
def bin_trees(n: int) -> Tuple[BinTree, ...]:
    if n == 0:
        return (None,)
    out = []
    for i in range(n):
        for l in bin_trees(i):
            for r in bin_trees(n - 1 - i):
                out.append(("bin", l, r))
    return tuple(out)


def main() -> None:
    for n in range(9):
        pt = len(forests_with_nodes(n))          # plane trees (n+1 nodes)
        bt = len(bin_trees(n))
        assert pt == bt == catalan(n)
        print(f"n={n:2d}  count={pt:6d}  C_n={catalan(n):6d}")


if __name__ == "__main__":
    main()

"""Demonstrate the Knuth transform is a size-preserving bijection."""
from functools import lru_cache
from typing import Optional, Tuple

PlaneTree = Tuple[str, Tuple]
Forest = Tuple[PlaneTree, ...]
BinTree = Optional[Tuple[str, "BinTree", "BinTree"]]


def forest_to_bin(f: Forest) -> BinTree:
    if not f:
        return None
    first, *rest = f
    _, children = first
    return ("bin", forest_to_bin(tuple(children)), forest_to_bin(tuple(rest)))


def bin_to_forest(b: BinTree) -> Forest:
    if b is None:
        return ()
    _, l, r = b
    return (("node", bin_to_forest(l)),) + bin_to_forest(r)


def forest_nodes(f: Forest) -> int:
    return sum(1 + forest_nodes(t[1]) for t in f)


def bin_internal(b: BinTree) -> int:
    if b is None:
        return 0
    _, l, r = b
    return 1 + bin_internal(l) + bin_internal(r)


@lru_cache(maxsize=None)
def forests_with_nodes(n: int) -> Tuple[Forest, ...]:
    if n == 0:
        return ((),)
    out = []
    for k in range(1, n + 1):
        for g in forests_with_nodes(k - 1):
            first = ("node", g)
            for rest in forests_with_nodes(n - k):
                out.append((first,) + rest)
    return tuple(out)


def main() -> None:
    for n in range(7):
        for f in forests_with_nodes(n):
            b = forest_to_bin(f)
            assert bin_to_forest(b) == f
            assert bin_internal(b) == forest_nodes(f) == n
        print(f"n={n}: all forests round-trip and preserve size  [OK]")


if __name__ == "__main__":
    main()

"""Enumerate Dyck paths and confirm equinumerosity with plane trees."""
from functools import lru_cache
from math import comb
from typing import Iterator, Tuple


def catalan(n: int) -> int:
    return comb(2 * n, n) // (n + 1)


def dyck_paths(n: int) -> Iterator[Tuple[int, ...]]:
    def rec(pref: Tuple[int, ...], up: int, down: int):
        if up == n and down == n:
            yield pref
            return
        if up < n:
            yield from rec(pref + (1,), up + 1, down)
        if down < up:
            yield from rec(pref + (-1,), up, down + 1)
    yield from rec((), 0, 0)


@lru_cache(maxsize=None)
def plane_trees(n: int) -> int:
    """Number of plane trees with n+1 nodes = number of plane forests, n nodes."""
    if n == 0:
        return 1
    return sum(plane_trees(k - 1) * plane_trees(n - k) for k in range(1, n + 1))


def main() -> None:
    for n in range(8):
        d = sum(1 for _ in dyck_paths(n))
        t = plane_trees(n)
        assert d == t == catalan(n)
        print(f"semilength {n}: {d} Dyck paths = {t} plane trees = C_{n}={catalan(n)}")


if __name__ == "__main__":
    main()

